function renderMap(day){const all=(currentJourney?.entries||[]).filter(e=>e.type==='poi'||e.type==='meal'&&e.restaurant).map(e=>e.type==='poi'?{...e.poi,number:e.index+1}:{...e.restaurant,number:'M'}).filter(hasCoords),base=hasCoords(plan.settings.basePoint)?{...plan.settings.basePoint,number:'S'}:null,publicIds=new Set([...pois,...(data.restaurants||[]),...(data.bases||[])].map(p=>p.id)),privatePoints=[...all,...(base?[base]:[])].filter(p=>p.custom||!publicIds.has(p.id)),shown=all.filter(p=>allowPrivateMap||!p.custom&&publicIds.has(p.id)),shownBase=base&&(allowPrivateMap||publicIds.has(base.id))?base:null;setMapPoints(shownBase?[shownBase,...shown,shownBase]:shown,{context:plan.settings.region+'|'+day.date,segments:currentJourney.legs.filter(l=>hasCoords(l.from)&&hasCoords(l.to)&&(allowPrivateMap||publicIds.has(l.from.id)&&publicIds.has(l.to.id))).map(l=>({fromId:l.from.id,toId:l.to.id,modeCode:l.modeCode||'transit',mode:l.mode}))});$('#mapActions').innerHTML=shown.map(p=>`<div class="map-link">${p.number}. ${esc(p.name)} ${mapLink(p)} ${link(p.coordinateSource,'좌표 출처')}</div>`).join('');$('#privateMapChoice').hidden=!privatePoints.length;$('#includePrivateMapBtn').setAttribute('aria-pressed',String(allowPrivateMap));$('#includePrivateMapBtn').textContent=allowPrivateMap?'직접 입력 위치 숨기기':'직접 입력 위치도 표시';if(plannerEntered&&tab==='Itinerary')setMapVisible(!mapCollapsed);highlightMapSelection(getMapSelection());}
function renderEntry(e,day,j){
  const full=renderEntryFull(e,day,j);
  if(e.type==='leg')return`<div class="transit-choice-row"><details class="transit-row"><summary><span class="transit-symbol">${modeIcon(e.modeCode||'transit')}</span><span>${esc(e.mode)}</span><strong>${e.durationUnknown?'시간 확인':e.minutes+'분'} · ${e.fare==null?'요금 확인':money(e.fare,e.currency)}</strong><span class="detail-caret">상세</span></summary><div class="transit-expanded">${e.choiceNeedsReview?`<p class="warning">${esc(e.choiceNotice)}</p>`:''}${full}</div></details><button class="choice-plus" type="button" data-leg-options="${esc(e.choiceKey)}" aria-label="${esc(e.from.name)}에서 ${esc(e.to.name)} 이동 대안 비교">+</button></div>`;
  if(e.type==='poi'){const p=e.poi;return`<article class="timeline-item"><div class="time-rail"><strong>${clockLabel(e.start)}</strong><span>${p.duration}분</span></div><details class="place-card"><summary data-map-point="${esc(p.id)}" aria-controls="routeMap"><span class="place-index">${e.index+1}</span><div><h4>${esc(p.name)}</h4><p>${esc(p.district||CITY[p.city])}</p><div class="card-chips"><span>${priceLabel(p)}</span>${plan.selected.some(s=>s.id===p.id&&s.priority==='must')?'<span class="required-chip">필수</span>':''}</div></div><span class="detail-caret">티켓·상세</span></summary><div class="place-expanded">${full}</div></details></article>`;}
  if(e.type==='meal'&&e.kind==='breakfast')return`<article class="timeline-item"><div class="time-rail"><strong>${clockLabel(e.start)}</strong><span>아침</span></div>${full}</article>`;
  if(e.type==='meal')return`<article class="timeline-item meal-choice-row"><div class="time-rail"><strong>${clockLabel(e.start)}</strong><span>${e.minutes}분</span></div><details class="place-card meal-compact"><summary ${e.restaurant?`data-map-point="${esc(e.restaurant.id)}" aria-controls="routeMap"`:""}><span class="place-index">M</span><div><h4>${e.kind==='dinner'?'저녁':'점심'} · ${esc(e.restaurant?.name||'자유 식사')}</h4><p>${esc(e.restaurant?.cuisine||'원하는 곳에서 한 끼')}</p><div class="card-chips"><span>1인 예산 ${money(e.budget,j.currency)}</span></div></div><span class="detail-caret">상세</span></summary><div class="place-expanded">${e.mealNeedsReview?'<p class="warning">날짜·영업조건이 바뀌어 식당 선택을 다시 확인해 주세요.</p>':''}${full}</div></details><button class="choice-plus meal-plus" type="button" data-meal-options="${e.kind}" aria-label="${e.kind==='dinner'?'저녁':'점심'} 대체 식당 보기">+</button></article>`;
  return full;
}
function compactBudget(){const box=$('#dayBudget .day-cost-card');if(!box)return;const details=document.createElement('details');details.className='day-cost-card';const summary=document.createElement('summary');const head=box.firstElementChild;while(head.firstChild)summary.append(head.firstChild);details.append(summary);head.remove();while(box.firstChild)details.append(box.firstChild);box.replaceWith(details);}

function renderRecommendations(){const options=nearby(plan,dayIndex,pois,dict);$('#recommendations').innerHTML=options.map(p=>`<article class="rec"><h4>${esc(p.name)}</h4><p>${p.near===null?'이 도시에 있는 곳':`일정 장소에서 직선 ${p.near.toFixed(1)}km`} · ${p.liked?'선택한 취향과 맞아요':esc(CATEGORY[p.category])}<br>${p.over?`명소 추가만으로 약 ${formatMinutes(p.over)} 초과돼요.`:`명소 추가 시 약 ${formatMinutes(p.extra)} 더 필요해요.`}</p><div class="rec-bottom"><span>${priceLabel(p)}</span><button data-add-rec="${esc(p.id)}">일정에 추가</button></div></article>`).join('')||'<p class="field-help">이날 동선 주변의 미방문 추천을 모두 확인했어요.</p>';}
function renderPasses(){
  const day=plan.days[dayIndex],j=currentJourney||itineraryFor(dayIndex),region=plan.settings.region,cities=new Set(plan.days.flatMap(d=>d.stops).map(id=>dict[id].city));
  const products=(data.passes||[]).filter(p=>p.city==='both'?['both','osaka','kyoto'].includes(region):cities.has(p.city)||(!cities.size&&matchesRegion(p.city,region)));
  const chosen=products.filter(p=>compare.has(p.id)),sum=chosen.reduce((n,p)=>n+(p.price||0),0);
  const comparison=chosen.length>1?`<div class="warning">선택한 ${chosen.length}개 상품 합계 ${money(sum,j.currency)} (각 1매). 아래 계산은 상품별 단독 비교입니다. 함께 구매하면 교통·입장 혜택이 겹칠 수 있어요.</div>`:'';
  $('#passCompare').innerHTML=`<div class="pass-day-select"><label for="passDay">혜택을 비교할 날짜</label><select id="passDay">${plan.days.map((d,i)=>`<option value="${i}" ${i===dayIndex?'selected':''}>DAY ${i+1} · ${formatDate(d.date)}</option>`).join('')}</select><p class="field-help">확인된 단품 요금만 비교합니다. 미확인 교통비·시간 조건부 혜택은 절감액에 넣지 않아요.</p></div>`+comparison+products.map(p=>{
    const c=passEstimate(p,j,day,dict),cur=p.currency||currencyFor(p.city),covered=c.covered.map(id=>dict[id].name);
    const formula=c.comparable?`<div class="cost-comparison"><div><small>단품 확인분</small><b>${money(c.baseline,cur)}</b></div><div><small>패스 + 남은 단품</small><b>${money(c.withPass,cur)}</b></div><p>${c.difference>0?`확인된 항목만 보면 패스가 ${money(c.difference,cur)} 적어요.`:c.difference<0?`확인된 항목만 보면 단품이 ${money(-c.difference,cur)} 적어요.`:'확인된 항목의 금액이 같아요.'} ${c.unknown?'미확인 항목이 있어 최종 최저가를 뜻하지 않습니다.':''}</p></div>`:'<div class="pass-match">이 일정에서 비교할 수 있는 포함 혜택·운임이 충분히 확인되지 않았거나, 여러 날·무료입장 횟수 조건을 별도로 검토해야 해요. 자동 절감액을 표시하지 않습니다.</div>';
    return`<article class="pass-card"><div class="pass-top"><div><div class="pass-city">${p.city==='both'?'오사카 · 교토':esc(CITY[p.city]||'여행 교통')} · 성인 기준</div><h3>${esc(p.name)}</h3></div><div class="pass-price">${money(p.price,cur)}<small>${esc(p.priceLabel||'대표 상품 1인')}</small></div></div><p>${esc(p.coverage||'')}</p>${p.priceVariants?.length?`<p class="small">${p.priceVariants.map(v=>esc(typeof v==='string'?v:(v.label||v.name||v.condition||'')+' '+(v.price!==undefined?money(v.price,cur):''))).join(' · ')}</p>`:''}${!c.valid?'<div class="warning">선택한 날짜가 이 상품의 확인된 판매·사용 기간 밖입니다. 해당 날짜의 유효 상품을 확인하세요.</div>':''}${formula}${covered.length?`<p class="small">${dayIndex+1}일차 포함 명소: ${esc(covered.join(', '))} · 별도 입장권 중복 구매 주의</p>`:''}<div class="pass-details"><div><b>사용 조건</b><span>${esc(p.validity||'공식 사이트 확인 필요')}</span></div><div><b>취소 · 환불</b><span>${esc(p.cancellation||'판매처에서 확인 필요')}</span></div></div>${p.eligibility?`<p class="small">이용 자격 · ${esc(p.eligibility)}</p>`:''}${p.exclusions?`<p class="small">주의 · ${esc(p.exclusions)}</p>`:''}${p.conditionalBenefits?.length?`<p class="small">조건부 혜택 · ${esc(p.conditionalBenefits.map(v=>typeof v==='string'?v:v.description||v.condition||'조건 확인 필요').join(' / '))}</p>`:''}<div class="pass-bottom"><label style="margin:0;font-size:12px;font-weight:400;display:flex;gap:7px;align-items:center"><input type="checkbox" data-compare="${esc(p.id)}" ${compare.has(p.id)?'checked':''}> 함께 비교</label><div class="inline-links">${link(p.purchaseUrl||p.officialUrl,p.purchaseUrl?'공식 구매 페이지':'공식 상품 안내','button secondary compact')}${link(p.klookUrl,'Klook 해당 상품','button secondary compact')}${projectMode?`<button type="button" class="button secondary compact" data-project-pass="${esc(p.id)}">예약 목록에 담기</button>`:''}</div></div><p class="field-help">확인일 ${esc(p.checkedAt||data.checkedAt)} · ${p.klookUrl?'Klook 가격은 선택한 날짜·옵션에서 다시 확인 · ':''}실시간 가격 아님</p></article>`;
  }).join('');
  if(!products.length)$('#passCompare').insertAdjacentHTML('beforeend','<div class="notice">이 지역의 검증된 교통권 정보를 아직 제공하지 않습니다.</div>');
  const tickets=(data.catalogTickets||[]).filter(t=>day.stops.includes(t.poiId));
  $('#ticketCompare').innerHTML='<div class="section-lead"><h3>오늘의 입장권, 판매처별로 확인.</h3><p>공식 상품과 Klook의 구성·입장 시간·취소 규정을 맞춰 보세요. 실제 예약은 각 판매처에서 진행합니다.</p></div>'+tickets.map(t=>{const p=dict[t.poiId],cur=t.currency||currencyFor(p.city);return`<article class="ticket-compare-card"><h3>${esc(p.name)}</h3><div class="ticket-price-grid"><div><span>공식 가격</span><b>${money(t.officialPrice??p.price,cur)}</b>${link(t.officialUrl,t.officialLinkType?'공식 안내·구매 연결':'공식 티켓 확인','button secondary compact')}</div><div><span>Klook</span><b>${!t.klookUrl?'미확인':t.klookPrice==null?'날짜·옵션 확인':money(t.klookPrice,cur)}</b>${t.klookUrl?link(t.klookUrl,'해당 상품 확인','button secondary compact'):'<small>검증된 상품 링크 없음</small>'}</div></div><p>${esc(t.priceScope||p.priceScope||'세부 상품 구성을 구매처에서 확인해 주세요.')}</p><p class="field-help">취소: ${esc(t.cancellation||'판매처·선택한 옵션에 따라 다름. 구매 화면 확인 필요')} · ${esc(t.checkedAt||data.checkedAt)} 확인</p></article>`}).join('');
  if(!tickets.length)$('#ticketCompare').insertAdjacentHTML('beforeend','<p class="notice">이날 선택한 장소에는 검증된 판매처 비교 자료가 없어요. 일정 카드의 공식 안내를 확인해 주세요.</p>');
}
function renderSources(){const ids=[...new Set([...plan.days.flatMap(d=>d.stops),...plan.pending])];$('#sourceList').innerHTML=`<h3>내 일정의 정보 출처</h3><p>가격·상품 확인일 ${esc(data.checkedAt)}. 선택한 여행일의 영업·요금·재고를 보장하지 않습니다. 노선과 요금이 확인된 구간도 전체 문전 이동시간은 추정일 수 있어요.</p>${ids.filter(id=>dict[id]).map(id=>{const p=dict[id];return`<details><summary>${esc(p.name)} ${p.custom?'· 직접 입력':''}</summary><p>${p.custom?'직접 입력한 장소입니다. 주소·운영·요금을 확인해 주세요.':`${link(p.officialUrl,'공식 장소 정보')}<br>${link(p.coordinateSource,'좌표 출처')}<br>${esc(p.priceNote||p.priceScope||'특별 전시·체험은 별도 요금일 수 있습니다.')}<br>${esc(p.hours||'영업시간·휴무일 재확인 필요')}<br>${esc(p.closureNote||'')}`}</p></details>`}).join('')}<details><summary>추천 순위·이동·비용 계산 방식</summary><p>추천순은 선택한 취향, 체류시간, 입장료를 기준으로 합니다. 공식 인기순위나 후기 평점이 아닙니다. 교통권 비교는 명시된 포함 시설과 검증된 구간만 계산하며, 미확인 항목은 합계에서 빠집니다.</p><p>식비·항공·숙박은 직접 입력한 예산입니다. 빈 금액은 미확정으로 표시하고, 전체 인원 항공 총액과 객실×박수 숙박비를 중복 계산하지 않습니다. 식당 가격이 확인되면 메뉴 범위를 따로 표시하고, 이 예산을 실제 결제액이라고 설명하지 않습니다.</p></details><details><summary>공식 데이터 원본·이용조건</summary>${(data.sourceCatalog||[]).filter((item,i,all)=>item.licenseUrl||i===all.findIndex(x=>x.url===item.url)).map(item=>`<p>${link(item.url,item.title||item.publisher||'공식 원본')}${item.use?' · '+esc(item.use):''}${item.licenseUrl?'<br>'+link(item.licenseUrl,'원본 이용조건'):''}${item.redistributionNotice?'<br>'+esc(item.redistributionNotice):''}</p>`).join('')}</details><details><summary>사진과 서비스 안내</summary><p>사진: ${link('https://commons.wikimedia.org/wiki/File:Skyline_view_of_Osaka.jpg','Ian G Shingler · Wikimedia Commons')} · ${link('https://creativecommons.org/licenses/by-sa/4.0/','CC BY-SA 4.0')} · 크롭·해상도·색조 조정</p><p>일반 구매 연결에는 제휴 식별자를 붙이지 않았으며 예약·결제를 대행하지 않습니다. 준비 중인 제휴 위젯은 항공권 화면에 상태와 조건을 별도로 표시합니다. 외부 링크는 누를 때만 해당 판매처나 지도에서 열립니다.</p></details>`;}
function switchTab(name){if(name!=='Itinerary'&&isMapVisible())setMapVisible(false);tab=name;if(name==='Flights')renderFlights();for(const n of['Discover','Itinerary','Passes','Flights','Sources']){$('#tab'+n).classList.toggle('active',n===name);$('#tab'+n).setAttribute('aria-selected',String(n===name));$('#'+n[0].toLowerCase()+n.slice(1)+'Panel').hidden=n!==name}if(plannerEntered&&name==='Itinerary'&&plan)setMapVisible(!mapCollapsed);}
function exportTrip(){
  if(!plan)return;let out=`여행 설계 · BANDAL\n${$('#tripTitle').textContent}\n성인 ${plan.settings.travelers||1}명 · 개별 교통/티켓 가격은 1인 기준\n${plan.settings.start} ~ ${plan.settings.end}\n\n`;
  plan.days.forEach((d,i)=>{const j=itineraryFor(i);out+=`DAY ${i+1} · ${formatDate(d.date)}\n`;j.entries.forEach(e=>{if(e.type==='origin')out+=`${clockLabel(e.start)} ${e.label}: ${e.name}\n`;if(e.type==='hotelAccess')out+=`숙소에서 거점까지: ${e.minutes==null?'시간 미확인':e.minutes+'분 (사용자 입력)'}\n`;if(e.type==='leg')out+=`${clockLabel(e.start)} ${e.mode}: ${e.from.name} → ${e.to.name}, 약 ${e.minutes}분, ${e.fare==null?'운임 미확인':money(e.fare,e.currency)}\n${e.line?e.line+' · '+(e.fromStation||'')+' → '+(e.toStation||'')+'\n':''}${e.timeBasis}\n${e.officialUrl||e.routeUrl}\n`;if(e.type==='poi')out+=`${clockLabel(e.start)} ${e.poi.name} · 체류 ${e.poi.duration}분 · ${priceLabel(e.poi)}\n${e.poi.officialUrl||'직접 입력'}\n`;if(e.type==='meal')out+=`${clockLabel(e.start)} 식사: ${e.restaurant?.name||'자유 식사'} · ${e.minutes}분 · 나의 예산 ${money(e.budget,j.currency)}\n${e.restaurant?.officialUrl||''}\n`;if(e.type==='break')out+=`${clockLabel(e.start)} 휴식 ${e.minutes}분\n`;});out+=`성인 ${plan.settings.travelers||1}명 확인 금액+입력한 식비 예산: ${money(j.subtotal*(plan.settings.travelers||1),j.currency)}. 미확인 입장료 ${j.unknownAttractions}곳, 운임 ${j.unknownFares}구간 제외. 숙박비 제외.\n\n`;});
  const fx=fxRate(currencyFor(plan.settings.region));if(fx)out+=`원화 환산: ${fx.source} · ${fx.date} 기준. 결제·환전 수수료 제외.\n`;
  if(plan.costSettings)out+='항공·숙박 직접 입력 예산 (전체 인원 항공총액 / 객실당·박당 요금):\n'+JSON.stringify(plan.costSettings,null,2)+'\n';
  if(plan.bookingStatuses)out+='직접 확인한 예약 상태 (판매처 확인서 아님):\n'+Object.entries(plan.bookingStatuses).map(([id,s])=>`${dict[id.split(':poi:')[1]]?.name||id} · ${s.date} · ${s.booked?'직접 완료 표시':'미완료'}`).join('\n')+'\n';
  out+='날짜별 식당·이동 선택 (날짜가 바뀌면 재확인):\n'+JSON.stringify(plan.days.map(d=>({date:d.date,choices:d.choices||{}})),null,2)+'\n';
  out+='시각과 이동시간은 계획용입니다. 실제 교통·영업·휴관·예약·판매 가격을 구매 전에 확인하세요. 추천 동선은 휴리스틱이며 최적을 보장하지 않습니다.\n';
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+out],{type:'text/plain;charset=utf-8'}));a.download=`여행설계_${plan.settings.start}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('이동·식사·비용이 포함된 일정을 내보냈어요.');
}
function addSelected(id){if(!dict[id]||selected.some(s=>s.id===id))return;selected.push({id,priority:'must'});$('#placeSearch').value='';renderSelected();save();toast('여행 조건에 담았어요. 동선 만들기로 반영해 주세요.');}
function makePlan(sample=false,scroll=true){allowPrivateMap=false;$('#formError').hidden=true;try{const settings=readSettings(),previous=plan;snapshot();plan=generatePlan(settings,selected,[...pois,...custom]);plan.meals={};if(!sample&&previous?.settings.region===settings.region){plan.meals=JSON.parse(JSON.stringify(previous.meals||{}));plan.bookingStatuses=JSON.parse(JSON.stringify(previous.bookingStatuses||{}));plan.costSettings=JSON.parse(JSON.stringify(previous.costSettings||{}));plan.days.forEach((day,i)=>{if(previous.days[i]?.choices)day.choices=JSON.parse(JSON.stringify(previous.days[i].choices));});}plan.sample=sample;dayIndex=0;render();switchTab('Itinerary');if(scroll)$('#results').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return true;}catch(error){$('#formError').textContent=error.message;$('#formError').hidden=false;return false;}}
$('#tripForm').addEventListener('submit',e=>{e.preventDefault();if(makePlan())toast('숙소·이동·명소·식사가 이어지는 일정을 만들었어요.')});
$('#placeSearch').addEventListener('input',renderSearch);
$('#region').addEventListener('change',()=>{syncCityInput($('#region').value);refreshBaseOptions();refreshCurrency(true);renderSearch();renderDiscovery()});
$('#base').addEventListener('change',()=>$('#customBaseFields').hidden=$('#base').value!=='custom-base');
for(const id of['start','end'])$('#'+id).addEventListener('change',()=>{dateHint();scheduleAutoPlan()});
$('#tripForm').addEventListener('change',()=>{if(loaded){renderDiscovery();save()}});$('#advancedOptions').addEventListener('change',()=>{if(loaded){renderDiscovery();save()}});
$('#sampleBtn').addEventListener('click',()=>{const requested=$('#region').value,region=CITY_CATALOG.some(c=>c.key===requested)?requested:'both',defaults=regionDefaults(region),base=(data.bases||[]).find(b=>matchesRegion(b.city,region));applySettings({region,start:datePlus(14),end:datePlus(16),baseId:base?.id||'none',hotelName:'',hotelAccessMinutes:null,startTime:'09:00',transport:'auto',mealBudget:defaults.mealBudget,pace:'balanced',budget:'balanced',breakTime:90,interests:['culture','food','nature']});const wanted=region==='both'?['dotonbori','osaka-castle','fushimi-inari-taisha','kiyomizu-dera']:pois.filter(p=>p.city===region).slice(0,4).map(p=>p.id);selected=wanted.filter(id=>dict[id]).map(id=>({id,priority:'must'}));renderSelected();makePlan(true);});
$('#customBtn').addEventListener('click',()=>{$('#customName').value=$('#placeSearch').value;$('#customCity').value=$('#region').value==='both'?'osaka':$('#region').value;$('#customError').hidden=true;$('#customDialog').showModal()});
$('#privacyBtn').addEventListener('click',()=>$('#privacyDialog').showModal());
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#customForm').addEventListener('submit',e=>{e.preventDefault();const name=$('#customName').value.trim(),lat=$('#customLat').value,lng=$('#customLng').value,city=$('#customCity').value,duration=Number($('#customDuration').value);if(!name)return;if((lat||lng)&&!validCoordinates(lat,lng,city)){$('#customError').textContent='선택한 도시의 지원 명소에서 60km 이내 위도·경도를 함께 입력하거나 둘 다 비워 주세요.';$('#customError').hidden=false;return;}if(!Number.isFinite(duration)||duration<15||duration>600){$('#customError').textContent='체류시간은 15~600분 사이로 입력해 주세요.';$('#customError').hidden=false;return;}const p={id:'custom-'+crypto.randomUUID(),name,city,lat:lat?Number(lat):null,lng:lng?Number(lng):null,duration,category:'custom',price:null,currency:currencyFor(city),custom:true};custom.push(p);selected.push({id:p.id,priority:'must'});$('#customDialog').close();$('#customForm').reset();$('#placeSearch').value='';renderSelected();save();toast('내 장소를 추가했어요. 동선을 만들면 반영됩니다.');});
$('#undoBtn').addEventListener('click',()=>{if(history.length){plan=JSON.parse(history.pop());selected=JSON.parse(JSON.stringify(plan.selected||[]));applySettings(plan.settings);renderSelected();render();toast('이전 일정으로 되돌렸어요.')}});
$('#exportBtn').addEventListener('click',exportTrip);
setupFlightWidget();
$('#flightShortcut').addEventListener('click',()=>{switchTab('Flights');$('#flightsPanel').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});$(window.matchMedia('(max-width: 650px)').matches?'#flightPageLink':'#openFlightWidget').focus();});
const tabs=['Discover','Itinerary','Passes','Flights','Sources'];tabs.forEach(n=>$('#tab'+n).addEventListener('click',()=>switchTab(n)));
$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let i=tabs.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;switchTab(tabs[i]);$('#tab'+tabs[i]).focus()});
$('#clearBtn').addEventListener('click',()=>{if(!confirm('이 브라우저에 저장된 여행을 지울까요? 내보낸 파일은 유지돼요.'))return;localStorage.removeItem(key);plan=null;selected=[];custom=[];history=[];setMapVisible(false);setMapPoints([]);clearTimeout(autoPlanTimer);$('#citySearch').value='';$('#region').value='both';for(const id of['hotelName','baseName','baseLat','baseLng','hotelAccess','flightOrigin'])$('#'+id).value='';$('#start').value=datePlus(14);$('#end').value=datePlus(16);$('#travelers').value='1';refreshBaseOptions('none');refreshCurrency(true);refreshDict();renderSelected();render();dateHint();toast('이 기기의 여행 정보를 지웠어요.')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.city){chooseCity(d.city);return;}if(d.select)addSelected(d.select);if(d.unselect){selected=selected.filter(s=>s.id!==d.unselect);renderSelected();save()}if(d.day!==undefined){dayIndex=Number(d.day);render()}if(d.remove)mutate(()=>{plan.days[dayIndex].stops=plan.days[dayIndex].stops.filter(id=>id!==d.remove);plan.selected=plan.selected.filter(s=>s.id!==d.remove)},'일정에서 뺐어요. 되돌리기로 복원할 수 있어요.');if(d.up||d.down)mutate(()=>{const ids=plan.days[dayIndex].stops,i=ids.indexOf(d.up||d.down),j=i+(d.up?-1:1);if(j>=0&&j<ids.length)[ids[i],ids[j]]=[ids[j],ids[i]];});if(d.addRec)mutate(()=>{plan.days[dayIndex].stops=optimizeRoute([...plan.days[dayIndex].stops,d.addRec],dict,plan.settings.basePoint);plan.generated.push(d.addRec)},'추천 장소를 추가하고 이동을 다시 계산했어요.');if(d.placePending)mutate(()=>{plan.pending=plan.pending.filter(id=>id!==d.placePending);plan.days[dayIndex].stops.push(d.placePending)},'확인 필요 상태로 배치했어요. 실제 위치·운영을 확인해 주세요.');if(b.id==='reorderBtn')mutate(()=>plan.days[dayIndex].stops=optimizeRoute(plan.days[dayIndex].stops,dict,plan.settings.basePoint),'가까운 장소부터 동선을 다시 정리했어요.');});
document.addEventListener('change',e=>{const d=e.target.dataset;if(e.target.id==='passDay'){dayIndex=Number(e.target.value);render()}if(d.priority){const item=selected.find(s=>s.id===d.priority);if(item)item.priority=e.target.value;save()}if(d.move){const target=Number(e.target.value);mutate(()=>{plan.days[dayIndex].stops=plan.days[dayIndex].stops.filter(id=>id!==d.move);plan.days[target].stops=optimizeRoute([...plan.days[target].stops,d.move],dict,plan.settings.basePoint)},`${target+1}일차로 옮겼어요.`)}if(d.meal!==undefined)mutate(()=>{const day=plan.days[Number(d.meal)];day.choices??={};day.choices[e.target.dataset.mealKind==='dinner'?'dinner':'meal']={id:e.target.value,reviewedDate:day.date}},'식당과 이동시간을 다시 반영했어요.');if(d.compare){e.target.checked?compare.add(d.compare):compare.delete(d.compare);renderPasses()}});
async function init(){
  try{
    const [baseResponse,extraResponse,referralResponse,worldResponse,fxResponse,seoulResponse,europeResponse]=await Promise.all([fetch('./data.json'),fetch('./enrichment.json'),fetch('./referrals.json'),fetch('./world.json'),fetch('./fx.json'),fetch('./seoul.json'),fetch('./europe.json')]);if(fxResponse.ok)configureFx(await fxResponse.json());referrals=referralResponse.ok?await referralResponse.json():null;
    if(!baseResponse.ok)throw Error('data');data=await baseResponse.json();const extra=extraResponse.ok?await extraResponse.json():{};
    if(!worldResponse.ok)throw Error('world');const world=await worldResponse.json();if(!seoulResponse.ok)throw Error('seoul');const seoul=await seoulResponse.json();if(!europeResponse.ok)throw Error('europe');const europe=await europeResponse.json();
    for(const k of['pois','passes','bases','restaurants','transitLegs','catalogTickets','airports'])data[k]=[...(data[k]||[]),...(extra[k]||[]),...(world[k]||[]),...(seoul[k]||[]),...(europe[k]||[])];
    data.sourceCatalog=[...(data.sources||[]),...(extra.sources||[]),...(world.sources||[]),...(seoul.sources||[]),...(europe.sources||[])];for(const item of [...(extra.catalogPasses||[]),...(europe.catalogPasses||[])]){const pass=data.passes.find(p=>p.id===item.passId);if(pass)Object.assign(pass,{klookUrl:item.klookUrl,klookPrice:item.klookPrice,klookNotes:item.notes});}
    data.checkedAt=extra.checkedAt||data.checkedAt||data.meta?.checkedAt||'2026-10-08';
    pois=data.pois.map(p=>({...p,currency:p.currency||currencyFor(p.city)}));data.passes=data.passes.map(p=>({...p,currency:p.currency||currencyFor(p.city)}));refreshDict();
    $('#region').innerHTML=CITY_CATALOG.map(c=>`<option value="${c.key}">${esc(c.label)}</option>`).join('')+'<option value="other">다른 지역</option>';$('#region').value='both';$('#customCity').innerHTML=CITY_CATALOG.filter(c=>c.key!=='both').map(c=>`<option value="${c.key}">${esc(c.label)}</option>`).join('');$('.edition').innerHTML=(CITY_CATALOG.length-1)+' CITIES <span>베타</span>';$$('[data-supported-cities]').forEach(el=>el.textContent=SUPPORTED_NAMES);$('#start').value=datePlus(14);$('#end').value=datePlus(16);refreshBaseOptions();refreshCurrency();
    try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.custom)&&Array.isArray(saved.selected)){custom=saved.custom.filter(p=>p.custom&&typeof p.id==='string'&&typeof p.name==='string');refreshDict();selected=saved.selected.filter(s=>dict[s.id]);if(saved.settings)applySettings(saved.settings);if(saved.plan?.days?.length&&saved.plan.days.every(d=>Array.isArray(d.stops)&&d.stops.every(id=>dict[id]))){plan=saved.plan;plan.pending=(plan.pending||[]).filter(id=>dict[id]);plan.meals??={};dayIndex=Math.max(0,Number(saved.dayIndex)||0);}}}catch{localStorage.removeItem(key)}
    renderSelected();render();dateHint();loaded=true;projectController=createProjectController({getSnapshot:editorSnapshot,restoreSnapshot:restoreEditorSnapshot,generateStay:generateProjectStay,getData:()=>({...data,pois}),defaultDate:datePlus,money,toast,setMode:setProjectMode,restoreSingle:restoreSingleSnapshot,clearSingle:clearSingleSnapshot});initializeOnboarding();initializeTripOverview();if(findCity($('#citySearch').value)&&(!plan||plan.settings.region!==$('#region').value||plan.settings.start!==$('#start').value||plan.settings.end!==$('#end').value))scheduleAutoPlan();
  }catch(error){$('#formError').hidden=false;$('#formError').textContent='장소 정보를 불러오지 못했어요. 페이지를 새로고침해 주세요.';$('#tripForm button[type=submit]').disabled=true;$('#sampleBtn').disabled=true;$('#entryStatus').textContent='도시 정보를 불러오지 못했어요. 페이지를 새로고침해 주세요.';console.error(error)}
}
const normalizeCity=value=>String(value||'').toLowerCase().replace(/\s+/g,'');
function findCity(value){const q=normalizeCity(value);return CITY_CATALOG.find(c=>normalizeCity(c.label)===q||c.aliases.some(a=>normalizeCity(a)===q))}
function syncCityInput(region){const city=CITY_CATALOG.find(c=>c.key===region);$('#citySearch').value=city?.label||'';$('#cityHelp').textContent=city?`${city.country} · 확인된 명소 ${pois.filter(p=>matchesRegion(p.city,city.key)).length}곳의 초기 자료로 계획해요.`:`현재 ${SUPPORTED_NAMES}를 지원해요.`;}
function cityMatches(){const q=normalizeCity($('#citySearch').value);return CITY_CATALOG.filter(c=>!q||normalizeCity(c.label).includes(q)||c.aliases.some(a=>normalizeCity(a).includes(q)))}
function renderCitySuggestions(){const matches=cityMatches();cityActiveIndex=-1;$('#citySuggestions').innerHTML=matches.map(c=>`<button type="button" class="city-suggestion" role="option" id="city-option-${c.key}" aria-selected="false" data-city="${c.key}"><span>${esc(c.label)}</span><span>${esc(c.country)}</span></button>`).join('')||'<div class="city-empty">아직 이 도시의 데이터가 없어요. 지원 도시 목록에서 골라 주세요.</div>';$('#citySuggestions').hidden=false;$('#citySearch').setAttribute('aria-expanded','true');}
function closeCitySuggestions(){$('#citySuggestions').hidden=true;$('#citySearch').setAttribute('aria-expanded','false');$('#citySearch').removeAttribute('aria-activedescendant');}
function chooseCity(key){const city=CITY_CATALOG.find(c=>c.key===key);if(!city)return;const changed=$('#region').value!==key;$('#region').value=key;syncCityInput(key);closeCitySuggestions();if(data){refreshBaseOptions();refreshCurrency(changed);if(changed)selected=selected.filter(s=>dict[s.id]&&matchesRegion(dict[s.id].city,key));renderSelected();}scheduleAutoPlan();}
function scheduleAutoPlan(){clearTimeout(autoPlanTimer);if(!loaded||!plannerEntered)return;autoPlanTimer=setTimeout(()=>{if(!findCity($('#citySearch').value))return;let candidate;try{candidate=readSettings()}catch(error){$('#formError').textContent=error.message;$('#formError').hidden=false;return;}if(plan&&JSON.stringify({...candidate,selected})===JSON.stringify({...plan.settings,selected:plan.selected}))return;const valid=makePlan(false,false);if(valid){$('#advancedOptions').removeAttribute('open');save();}},250);}
$('#breakfastIncluded').addEventListener('change',()=>{$('#breakfastBudget').disabled=$('#breakfastIncluded').checked;});
$('#citySearch').addEventListener('focus',renderCitySuggestions);
$('#citySearch').addEventListener('input',()=>{renderCitySuggestions();const exact=findCity($('#citySearch').value);if(exact){chooseCity(exact.key);}else{$('#cityHelp').textContent=cityMatches().length?'목록에서 여행할 도시를 골라 주세요.':'아직 지원하지 않는 도시예요. 기존 일정은 그대로 유지됩니다.';}});
$('#citySearch').addEventListener('keydown',event=>{let options=$$('#citySuggestions [data-city]');if(event.key==='Escape'){closeCitySuggestions();return;}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if($('#citySuggestions').hidden){renderCitySuggestions();options=$$('#citySuggestions [data-city]');}cityActiveIndex=(cityActiveIndex+(event.key==='ArrowDown'?1:-1)+options.length)%Math.max(1,options.length);options.forEach((o,i)=>{o.classList.toggle('active',i===cityActiveIndex);o.setAttribute('aria-selected',String(i===cityActiveIndex))});if(options[cityActiveIndex])$('#citySearch').setAttribute('aria-activedescendant',options[cityActiveIndex].id);}if(event.key==='Enter'){event.preventDefault();const key=options[cityActiveIndex<0?0:cityActiveIndex]?.dataset.city;if(key)chooseCity(key);else makePlan(false,false);}});
$('#citySearch').addEventListener('change',()=>{const exact=findCity($('#citySearch').value);if(exact)chooseCity(exact.key);});
$('#citySearch').addEventListener('blur',()=>setTimeout(closeCitySuggestions,150));
function renderRouteLinks(){
  const entries=currentJourney?.entries||[],points=entries.filter(e=>e.type==='poi'||e.type==='meal'&&e.restaurant).map(e=>e.type==='poi'?e.poi:e.restaurant).filter(hasCoords);
  if(hasCoords(plan.settings.basePoint)){points.unshift(plan.settings.basePoint);points.push(plan.settings.basePoint);}
  if(points.length<2){$('#routeOpenLink').innerHTML=points.length?link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(`${points[0].lat},${points[0].lng}`),'Google 지도에서 장소 보기','button secondary compact'):'';return;}
  const routes=[];for(let i=0;i<points.length-1;i+=4){const part=points.slice(i,i+5),url=new URL('https://www.google.com/maps/dir/');url.searchParams.set('api','1');url.searchParams.set('origin',`${part[0].lat},${part[0].lng}`);url.searchParams.set('destination',`${part.at(-1).lat},${part.at(-1).lng}`);if(part.length>2)url.searchParams.set('waypoints',part.slice(1,-1).map(p=>`${p.lat},${p.lng}`).join('|'));routes.push(url.href);}
  $('#routeOpenLink').innerHTML=`<div class="route-external">${routes.map((url,i)=>link(url,routes.length===1?'Google 지도에서 경로 확인':`Google 지도 경로 ${i+1}/${routes.length}`,'button secondary compact')).join('')}<p>클릭하면 선택한 장소 좌표가 Google 지도에 전달됩니다. 이동 수단은 지도에서 선택해 주세요.${routes.length>1?' 모바일 경유지 제한에 맞춰 나눠 열어요.':''}</p></div>`;
}
function resolveAirport(value){const q=String(value||'').trim();const known=[{code:'ICN',terms:['인천','incheon']},{code:'GMP',terms:['김포','gimpo']},{code:'PUS',terms:['부산','김해','busan','gimhae']},{code:'CJU',terms:['제주','jeju']}];if(/^[A-Za-z]{3}$/.test(q))return q.toUpperCase();const explicit=q.match(/(?:\s|\()([A-Za-z]{3})\)?$/);if(explicit)return explicit[1].toUpperCase();return known.find(a=>a.terms.includes(q.toLowerCase()))?.code||null;}
function flightAirports(){const region=plan.settings.region,known=(data.airports||[]).filter(a=>a.city===region).map(a=>({code:a.iata||a.code,name:`${a.name} ${a.iata||a.code}`,note:a.notes||'공항에서 도심까지의 이동은 별도입니다.',officialUrl:a.officialUrl}));if(known.length)return known;return region==='rome'?[{code:'FCO',name:'로마 피우미치노 FCO',note:'로마 피우미치노 공항(FCO) 기준 검색입니다. 다른 공항은 외부 사이트에서 비교해 주세요.'}]:[{code:'KIX',name:'오사카 간사이 KIX',note:region==='kyoto'?'교토는 오사카 간사이 공항(KIX)을 관문으로 검색해요. 공항에서 교토까지의 이동은 별도입니다.':'오사카 간사이 공항(KIX) 기준입니다. 이타미·고베 등 다른 공항은 외부 사이트에서 비교해 주세요.'}];}
function flightDestination(){const choices=flightAirports();return choices.find(c=>c.code===$('#flightAirport').value)||choices[0];}

function flightCriteria(){const origin=resolveAirport($('#flightOrigin').value),departure=$('#flightDeparture').value,ret=$('#flightReturn').value,destination=flightDestination();if(!origin)throw Error('출발 공항 이름이나 3자리 코드를 입력해 주세요. 서울은 인천 ICN 또는 김포 GMP를 골라 주세요.');if(!parseDate(departure)||!parseDate(ret)||ret<departure)throw Error('항공 출국일과 귀국 출발일을 확인해 주세요.');if(departure<datePlus(0))throw Error('항공권 검색은 오늘 이후 날짜로 조정해 주세요.');if(origin===destination.code)throw Error('출발 공항과 도착 공항이 같아요. 출발지를 확인해 주세요.');return{origin,destination:destination.code,destinationName:destination.name,departure,return:ret,adults:plan.settings.travelers||1};}
function flightUrl(provider,criteria){if(provider.id==='kayak')return`https://www.kayak.co.kr/flights/${criteria.origin}-${criteria.destination}/${criteria.departure}/${criteria.return}`;if(provider.id==='skyscanner')return`https://www.skyscanner.co.kr/transport/flights/${criteria.origin.toLowerCase()}/${criteria.destination.toLowerCase()}/${criteria.departure.slice(2).replaceAll('-','')}/${criteria.return.slice(2).replaceAll('-','')}/`;return provider.homeUrl;}
function flightText(criteria){return`${criteria.origin} → ${criteria.destinationName}\n출국 ${criteria.departure} / 귀국 출발 ${criteria.return}\n성인 ${criteria.adults}명 · 일반석\n외부 기본 검색은 성인 1명입니다. 인원·공항·수하물·환불 조건을 다시 확인하세요.`;}
function renderFlights(){
  if(!plan)return;const choices=flightAirports(),selectedAirport=$('#flightAirport').value,key=`${plan.settings.region}|${plan.settings.start}|${plan.settings.end}`;
  if(flightPlanKey!==key){$('#flightDeparture').value=plan.settings.start;$('#flightReturn').value=plan.settings.end;flightPlanKey=key;}
  $('#flightAirport').innerHTML=choices.map(a=>`<option value="${a.code}">${esc(a.name)}</option>`).join('');$('#flightAirport').value=choices.some(a=>a.code===selectedAirport)?selectedAirport:choices[0].code;const dest=flightDestination();$('#flightAirportHelp').textContent=dest.note;
  $('#flightTripSummary').innerHTML=`<div><small>도착 여행지</small><b>${esc(plan.settings.region==='both'?'오사카 · 교토':CITY[plan.settings.region])}</b></div><div><small>여행 일정</small><b>${esc(plan.settings.start)} – ${esc(plan.settings.end)}</b></div><div><small>여행 인원</small><b>성인 ${plan.settings.travelers||1}명</b></div>`;
  let criteria=null;try{criteria=flightCriteria();$('#flightError').hidden=true;}catch(error){$('#flightError').textContent=error.message;$('#flightError').hidden=!$('#flightOrigin').value.trim();}
  $('#flightCriteria').hidden=!criteria;if(criteria)$('#flightCriteria').textContent=flightText(criteria);$('#copyFlightCriteria').disabled=!criteria;
  $('#flightProviders').innerHTML=(referrals?.providers||[]).map(p=>`<article class="flight-provider"><h4>${esc(p.name)}</h4><p>선택한 출발·도착 공항과 항공 날짜를 넣어 외부 검색을 열어요. 실제 가격은 그곳에서 확인합니다.</p>${criteria?link(flightUrl(p,criteria),'이 조건으로 항공권 검색','button secondary compact'):'<button type="button" class="button secondary compact" disabled>출발지를 먼저 입력해 주세요</button>'}<small>기본 성인 1명 · 일반석. ${plan.settings.travelers>1?'현재 여행 인원에 맞게 외부 사이트에서 변경하세요. ':''}검색 결과의 날짜·공항·통화와 수하물·환불 조건을 재확인해 주세요.</small></article>`).join('');
}
$('#flightAirport').addEventListener('change',renderFlights);$('#flightOrigin').addEventListener('input',renderFlights);$('#flightDeparture').addEventListener('change',renderFlights);$('#flightReturn').addEventListener('change',renderFlights);
$('#showMapBtn').addEventListener('click',()=>{mapCollapsed=isMapVisible();setMapVisible(!mapCollapsed);});
$('#fitDayMapBtn').addEventListener('click',async()=>{mapCollapsed=false;await setMapVisible(true);fitMapToDay();});
