function renderFx(){const cur=currencyFor(plan?.settings.region||$('#region').value),r=fxRate(cur);$('.fx-settings').hidden=cur==='KRW';$('#fxNotice').textContent=r?`${r.source} · ${r.date} 기준 · 결제·환전 수수료 제외`:'원화 환산 기준이 없어 현지 통화만 표시합니다.';$('#fxCurrencyLabel').textContent=`1 ${cur} = 원화`;$('#fxRateInput').value=r?.rate||'';$('#fxSource').innerHTML=link(fxSource(),'ECB 공식 환율 확인');$('#fxAge').textContent=r&&Date.now()-Date.parse(r.date+'T00:00:00Z')>4*86400000?'오래된 기준입니다. 실제 결제 환율을 확인하거나 직접 수정해 주세요.':'미래 여행일의 환율 예측이 아닌 예산 참고값입니다.';}
$('#applyFx').addEventListener('click',()=>{try{setFxOverride(currencyFor(plan.settings.region),Number($('#fxRateInput').value),datePlus(0));render();projectController?.rerender();toast('이 기기에서 사용할 환율을 적용했어요.')}catch(e){toast(e.message)}});
$('#resetFx').addEventListener('click',()=>{resetFxOverride(currencyFor(plan.settings.region));render();toast('저장된 ECB 기준 환율로 돌아왔어요.');});
function enterPlanner(){plannerEntered=true;$('#plannerSurface').hidden=false;$('#plannerSurface').inert=false;$('#plannerSurface').setAttribute('aria-hidden','false');$('#onboarding').hidden=true;$('#privacyBtn').hidden=false;if(plan){render();switchTab('Itinerary');}else scheduleAutoPlan();requestAnimationFrame(()=> (projectMode?$('#projectSelect'):$('#citySearch')).focus());}
function leavePlanner(){projectController?.flush();plannerEntered=false;clearTimeout(autoPlanTimer);setMapVisible(false);$('#plannerSurface').hidden=true;$('#plannerSurface').inert=true;$('#plannerSurface').setAttribute('aria-hidden','true');$('#privacyBtn').hidden=true;$('#onboarding').hidden=false;onboarding?.reset();$('#decidedBtn').focus();}
$('#backToStart').addEventListener('click',leavePlanner);

function editorSnapshot(){if(!plan)return null;let settings;try{settings=readSettings()}catch{settings=plan.settings;}return JSON.parse(JSON.stringify({settings,selected,custom,plan,dayIndex,history}));}
function setProjectMode(active){projectMode=active;clearTimeout(autoPlanTimer);$('.settings').hidden=active;$('#sampleBtn').hidden=active;for(const id of['citySearch','start','end'])$('#'+id).disabled=active;$('#clearBtn').disabled=active;$('#clearBtn').textContent=active?'프로젝트는 위 목록에서 삭제·복구할 수 있어요':'저장된 단일 일정 지우기';}
function restoreEditorSnapshot(snap){allowPrivateMap=false;clearTimeout(autoPlanTimer);projectRestoring=true;setMapVisible(false);setMapPoints([]);plan=snap?.plan?JSON.parse(JSON.stringify(snap.plan)):null;selected=JSON.parse(JSON.stringify(snap?.selected||plan?.selected||[]));custom=JSON.parse(JSON.stringify(snap?.custom||[]));history=JSON.parse(JSON.stringify(snap?.history||[]));dayIndex=snap?.dayIndex||0;refreshDict();if(plan)applySettings(snap.settings||plan.settings);else{$('#citySearch').value='';$('#region').value='both';$('#start').value=datePlus(14);$('#end').value=datePlus(16);for(const id of['hotelName','baseName','baseLat','baseLng','hotelAccess','flightOrigin'])$('#'+id).value='';refreshBaseOptions('none');refreshCurrency(true);}renderSelected();render();dateHint();switchTab('Itinerary');projectRestoring=false;}
function restoreSingleSnapshot(){let saved=null;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}restoreEditorSnapshot(saved);}
function clearSingleSnapshot(){localStorage.removeItem(key);clearFxOverrides();restoreEditorSnapshot(null);}
function generateProjectStay(stay,range){const defaults=regionDefaults(stay.city),settings={region:stay.city,start:range.start,end:range.end,pace:'balanced',budget:'balanced',interests:['culture','food','nature'],baseId:'none',basePoint:null,baseName:'',baseLat:'',baseLng:'',hotelName:'',hotelAccessMinutes:null,startTime:'09:00',transport:'auto',mealBudget:defaults.mealBudget,mealPreference:'nearby',breakTime:90,travelers:1};const generated=generatePlan(settings,[],pois);generated.meals={};return{settings,selected:[],custom:[],plan:generated,dayIndex:0,history:[]};}

function highlightMapSelection(id,source){const summaries=$$('#timeline [data-map-point]');for(const el of summaries){const active=el.dataset.mapPoint===id;(el.closest('.place-card')||(el.matches('.origin-card')?el:null))?.classList.toggle('map-selected',active);active?el.setAttribute('aria-current','true'):el.removeAttribute('aria-current');}if(source==='map'){const target=summaries.find(el=>el.dataset.mapPoint===id);if(target){const details=target.closest('details');if(details)details.open=true;target.scrollIntoView({block:'nearest',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}}
setMapSelectionHandler((id,meta)=>highlightMapSelection(id,meta.source));
document.addEventListener('click',event=>{const target=event.target.closest('#timeline [data-map-point]');if(!target)return;if(!focusMapPoint(target.dataset.mapPoint)){const p=dict[target.dataset.mapPoint]||(data.restaurants||[]).find(p=>p.id===target.dataset.mapPoint);toast(hasCoords(p)?'직접 입력 위치는 지도에서 따로 표시할 수 있어요.':'좌표가 없어 바로 선택할 수 없어요. 상세의 외부 지도로 위치를 확인해 주세요.');}});
document.addEventListener('keydown',event=>{const target=event.target.closest('#timeline .origin-card[data-map-point]');if(target&&['Enter',' '].includes(event.key)){event.preventDefault();target.click();}});
function updateMapKeyboardLayout(){const active=document.activeElement,editing=active?.matches?.('input,textarea,select'),keyboard=window.visualViewport&&window.visualViewport.height<window.innerHeight*.72;document.body.classList.toggle('form-editing',!!editing||!!keyboard);}
document.addEventListener('focusin',updateMapKeyboardLayout);document.addEventListener('focusout',()=>requestAnimationFrame(updateMapKeyboardLayout));window.visualViewport?.addEventListener('resize',updateMapKeyboardLayout);

function closeChoiceDialog(){$('#choiceDialog').close();}
function openLegChoices(key){const e=currentJourney?.legs.find(l=>l.choiceKey===key);if(!e)return;const day=plan.days[dayIndex],options=legCandidates(e.from,e.to,{...plan.settings,travelDate:day.date},data);$('#choiceTitle').textContent='이동 방법 비교';$('#choiceBody').innerHTML=`<p>${esc(e.from.name)} → ${esc(e.to.name)}</p><p class="field-help">${day.date} 기준 선택입니다. Google Maps에서 출발 날짜·시각을 직접 선택해 실제 경로를 확인하세요. 가격·운행을 실시간 조회하지 않아요.</p>${options.map(o=>`<article class="alternative-card ${o.optionId===e.optionId?'selected':''}"><h3>${modeIcon(o.modeCode)} ${esc(o.title)}</h3><p>${esc(o.reason)}</p><p><b>${o.durationUnknown?'소요시간 미확인':o.minutes+'분 · 예상'}</b> · ${o.fare==null?'운임 미확인':money(o.fare,o.currency)}</p><p class="field-help">${esc(o.timeBasis)}${o.fareScope?' · '+esc(o.fareScope):''}</p>${o.notes?`<p class="field-help">${esc(o.notes)}</p>`:''}${o.unavailableReason?`<p class="warning">${esc(o.unavailableReason)}</p>`:''}<div class="inline-links">${link(o.mapsUrl,'Google Maps 확인')}${link(o.officialUrl,'공식 노선·요금')}${link(o.klookUrl,'Klook 해당 상품')}</div><button class="button ${o.optionId===e.optionId?'secondary':'primary'} compact" type="button" data-leg-choice="${esc(o.optionId)}" data-leg-key="${esc(key)}" ${o.selectable?'':'disabled'}>${o.optionId===e.optionId?'이 방법 다시 확인':'이 방법으로 변경'}</button></article>`).join('')}`;$('#choiceDialog').showModal();}
function openMealChoices(kind='lunch'){const e=currentJourney?.entries.find(e=>e.type==='meal'&&e.kind===kind);if(!e)return;const day=plan.days[dayIndex];$('#choiceTitle').textContent=(kind==='dinner'?'저녁':'점심')+' 식당 후보';$('#choiceDialog').dataset.mealKind=kind;$('#choiceBody').innerHTML=`<p class="field-help">공식 정보가 있는 식당을 음식 취향과 동선의 직선거리로 비교합니다. Google 평점·리뷰와 실시간 영업은 확인하지 않았어요. 유명도 순위가 아니며 실제 메뉴 가격은 공식 페이지에서 확인하세요.</p>${(e.allCandidates||e.candidates).map(r=>`<article class="alternative-card ${r.id===e.restaurant?.id?'selected':''}"><h3>${esc(r.name)}</h3><p>${esc(r.cuisine||'공식 정보 기반 식당')}</p><p>${Number.isFinite(r.detourKm)?'직선거리 기준 우회 약 '+r.detourKm.toFixed(1)+'km'+(r.detourKm>2.5?' · 기존 추천 범위 밖, 이동 증가':''):'공식 좌표 미확인 · 자동 추천 제외. 직접 선택하면 지도 없이 임시 이동시간을 배정합니다.'}</p>${r.recommendationReason?`<p>${esc(r.recommendationReason)}</p>`:''}${r.hours?`<p class="field-help">${esc(r.hours)}</p>`:''}${r.notes?`<p class="field-help">${esc(r.notes)}</p>`:''}<p class="field-help">Google 평점 미확인 · 식비 합계에는 내 한 끼 예산을 사용합니다.</p><div class="inline-links">${link(r.officialUrl,'공식 메뉴·영업')}${link(r.reservationUrl,'예약 페이지')}${mapLink(r)}</div>${r.mealServices&&!r.mealServices.includes(kind)?'<p class="warning">이 식사 시간의 운영은 지원하지 않는 후보입니다.</p>':''}${isKnownClosed(r,day.date)?'<p class="warning">이 날짜는 알려진 휴무 조건에 해당해요.</p>':''}<button type="button" class="button primary compact" data-meal-choice="${esc(r.id)}" ${isKnownClosed(r,day.date)||r.mealServices&&!r.mealServices.includes(kind)?'disabled':''}>${r.id===e.restaurant?.id?'이 식당 다시 확인':'이 식당으로 변경'}</button></article>`).join('')||'<p>좌표가 확인된 식당 후보가 없어요. 식사 시간은 그대로 확보합니다.</p>'}<button type="button" class="button secondary full" data-meal-choice="none">식당 지정 없이 식사 시간만</button>`;$('#choiceDialog').showModal();}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||!plan)return;if(b.dataset.legOptions)openLegChoices(b.dataset.legOptions);if(b.hasAttribute('data-meal-options'))openMealChoices(b.dataset.mealOptions);if(b.dataset.legChoice){const key=b.dataset.legKey,id=b.dataset.legChoice;mutate(()=>{const day=plan.days[dayIndex];day.choices??={};day.choices.legs??={};day.choices.legs[key]={optionId:id,reviewedDate:day.date};},'이동 방법을 일정과 예산에 반영했어요.');closeChoiceDialog();$('#timeline [data-leg-options="'+key+'"]').focus();}if(b.dataset.mealChoice){const id=b.dataset.mealChoice;mutate(()=>{const day=plan.days[dayIndex];day.choices??={};day.choices[$('#choiceDialog').dataset.mealKind==='dinner'?'dinner':'meal']={id,reviewedDate:day.date};},'식당과 그 사이 이동을 다시 계산했어요.');closeChoiceDialog();$('#timeline [data-meal-options]').focus();}});

function overviewContext(){const context=projectController?.getOverviewContext();if(context)return context;if(!plan)return null;return{project:{id:'single',name:$('#tripTitle').textContent,start:plan.settings.start,end:plan.settings.end,stays:[{id:'single',city:plan.settings.region,days:plan.days.length,transferBefore:0,snapshot:editorSnapshot()}],bookingStatuses:plan.bookingStatuses||{},costSettings:plan.costSettings||{}},routes:{}};}
function initializeTripOverview(){tripOverview=createTripOverview({getContext:overviewContext,getData:()=>({...data,pois}),money,updateCosts:value=>{if(projectMode)projectController.updateCosts(value);else{plan.costSettings=value;save();}},updateStatus:(id,date,booked)=>{if(projectMode)projectController.updateBooking(id,date,booked);else{plan.bookingStatuses??={};plan.bookingStatuses[id]={booked,date,updatedAt:new Date().toISOString()};save();}}});}

function initializeOnboarding(){onboarding=createOnboarding({getData:()=>({...data,pois}),hasSaved:()=>!!plan||projectController.hasSaved(),enter:enterPlanner,selectCity:(city,prefs)=>{if(projectMode)projectController.openSingle();$$('#interests input').forEach(i=>i.checked=(prefs.categories||[]).includes(i.value));if(prefs.pace)$(`input[name=pace][value="${prefs.pace}"]`).checked=true;if(prefs.budget)$('#budget').value=prefs.budget;enterPlanner();chooseCity(city);}});}
$('#privacyBtn').hidden=true;
init();
